  for (const ch of body) {
    const s = document.createElement('span');
    if (/\d/.test(ch)) {
      s.className = 'odo__d';
      const c = document.createElement('span');
      c.className = 'odo__c';
      c.innerHTML = [...CELLS].map(x => '<i>' + x + '</i>').join('');
      s.appendChild(c);
    } else {
      s.className = 'odo__s';
      s.textContent = ch;
    }
    vis.appendChild(s);
  }
